<?php $pendingAccounts=all("SELECT u.id,u.full_name,u.email,u.position,o.name office_name FROM users u JOIN offices o ON o.id=u.office_id WHERE u.status='Pending' ORDER BY u.id");if($pendingAccounts):?>
<section class="panel"><div class="panel-heading"><div><h2>Account requests <span class="count-pill"><?=count($pendingAccounts)?></span></h2><p>Confirm each person’s identity and office before granting Requester access.</p></div></div><div class="form-body stack">
<?php foreach($pendingAccounts as $account):?><form action="actions.php" method="post" class="registration-review"><?=csrf()?><input type="hidden" name="action" value="review_registration"><input type="hidden" name="id" value="<?=$account['id']?>"><input type="hidden" name="return_to" value="index.php?page=users"><h3><?=e($account['full_name'])?></h3><p><?=e($account['email'])?><br><?=e($account['position'])?> · <?=e($account['office_name'])?></p><label>Confirm your administrator password<input type="password" name="confirmation_password" required autocomplete="current-password"></label><div class="form-actions"><button class="btn danger" name="decision" value="reject">Reject account</button><button class="btn primary" name="decision" value="approve">Approve Requester account</button></div></form><?php endforeach?>
</div></section><?php endif?>
